* Control Script
.control
  * Operating point analysis to evaluate bias currents
  op
  let idd = -i(vdd)
  let pwr = idd * 1.8
  print idd pwr v(vbiasn) v(vbiasp) v(vcmfb)

  * Transient analysis of S/H circuit (Baker Fig. 26.25 & Fig. 26.36)
  tran 100p 200n
  let vocm = (v(vop) + v(vom)) / 2
  let vdiff = v(vop) - v(vom)

  meas tran vocm_avg avg vocm from=100n to=200n
  meas tran vop_max max v(vop) from=100n to=200n
  meas tran vop_min min v(vop) from=100n to=200n
  meas tran vom_max max v(vom) from=100n to=200n
  meas tran vom_min min v(vom) from=100n to=200n
  meas tran vdiff_pkpk pp vdiff from=100n to=200n

  print vocm_avg vdiff_pkpk
  quit
.endc
.end

